<?php
if(PHP_SAPI!=="cli"){http_response_code(404);exit;}
$root="/home/u783725167/domains/cortarimagenscarrossel.online/public_html";
$backup=dirname($root)."/cic-adsense-backup-20261102";
require_once $root."/db_config.php";
$mysqli->set_charset("utf8mb4");
$extra=["carrossel-splitter-como-dividir-uma-arte-em-slides-automaticamente"=>base64_decode(""),
"ferramenta-online-para-cortar-imagens-de-carrossel-no-instagram"=>base64_decode("")];
$planned=[];$original=[];
foreach($extra as $slug=>$append){
 $stmt=$mysqli->prepare("SELECT id,slug,content FROM posts WHERE slug=? LIMIT 1");
 $stmt->bind_param("s",$slug);$stmt->execute();
 $row=$stmt->get_result()->fetch_assoc();$stmt->close();
 if(!$row){echo "MISSING_SLUG ".$slug."\n";exit(1);}
 $mark=substr($append,strpos($append,"id=")+4,50);
 if(strpos($row["content"],$mark)!==false){echo "ALREADY ".$slug."\n";continue;}
 $original[]=$row;
 $planned[]=["id"=>$row["id"],"slug"=>$slug,"content"=>$row["content"]."\n".$append];
}
if(!$planned){echo "EDITORIAL_ALREADY_APPLIED\n";exit;}
if(!is_dir($backup) && !mkdir($backup,0750,true)){echo "BACKUP_DIR_ERROR\n";exit(1);}
$bk=$backup."/posts_editorial_before_20261102.json";
if(!file_exists($bk) && file_put_contents($bk,json_encode($original,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT))===false){echo "BACKUP_ERROR\n";exit(1);}
try{
 $mysqli->begin_transaction();
 $stmt=$mysqli->prepare("UPDATE posts SET content=? WHERE id=?");
 foreach($planned as $item){$text=$item["content"];$id=(int)$item["id"];$stmt->bind_param("si",$text,$id);$stmt->execute();echo "UPDATED ".$item["slug"]."\n";}
 $stmt->close();$mysqli->commit();echo "EDITORIAL_DONE\n";
}catch(Throwable $e){$mysqli->rollback();echo "EDITORIAL_ERROR ".get_class($e)."\n";exit(1);}
